def find_minimum_k(n, function_values):
    for k in range(1, n + 1):
        is_idempotent = True
        for x in range(1, n + 1):
            result = x
            for _ in range(k):
                result = function_values[result - 1]
            if result != x:
                is_idempotent = False
                break
        if is_idempotent:
            return k
    return -1  # This line should never be reached

